test('Should ignore retry-after header when retryAfter option is false', async t => {
  const clock = FakeTimers.install()
  t.after(() => clock.uninstall())

  let retries = 0
  const handler = new RetryHandler(
    {
      method: 'GET',
      retryOptions: {
        retryAfter: false,
        maxRetries: 1,
        minTimeout: 500
      }
    },
    {
      dispatch () {
        retries++
      },
      handler: {}
    }
  )

  handler.onResponseError(null, {
    statusCode: 429,
    code: 'UND_ERR_REQ_RETRY',
    headers: {
      'retry-after': '60'
    }
  })

  // Retry must be scheduled by the exponential backoff (minTimeout = 500ms),
  // not by the Retry-After header (60s)
  await clock.tickAsync(500)

  t.assert.strictEqual(retries, 1)
})

test('Should use retry-after header for retries (date)', async t => {
  t = tspl(t, { plan: 3 })

  let counter = 0
  const chunks = []
  const server = createServer({ joinDuplicateHeaders: true })
  let checkpoint
  const dispatchOptions = {
    method: 'PUT',
    path: '/',
    headers: {
      'content-type': 'application/json'
    }
  }

  server.on('request', (req, res) => {
    switch (counter) {
      case 0:
        checkpoint = Date.now()
        res.writeHead(429, {
          'retry-after': new Date(
            checkpoint + 2000
          ).toUTCString()
        })
        res.end('rate limit')
        counter++
        return
      case 1:
        res.writeHead(200)
        res.end('hello world!')
        t.ok(Date.now() - checkpoint >= 1000)
        counter++
        return
      default:
        t.fail('unexpected request')
    }
  })

  server.listen(0, () => {
    const client = new Client(`http://localhost:${server.address().port}`)
    const handler = new RetryHandler(dispatchOptions, {
      dispatch: client.dispatch.bind(client),
